// Shanghai OSM-derived scenery extract, selected within 4km. Data ODbL 1.0.
// © OpenStreetMap contributors; https://www.openstreetmap.org/copyright
// This embedded gzip payload is the complete derived database, not an API key.
// Human-readable equivalent: assets/shanghai-core.json; see SCENERY-ROADMAP.md.
const PACKED = '';
let loaded;
export function loadShanghaiGeography() {
  if (!loaded) loaded = (async () => {
    if (typeof DecompressionStream === 'undefined') throw new Error('Shanghai scenery requires a modern browser with gzip DecompressionStream support.');
    const binary = atob(PACKED), bytes = new Uint8Array(binary.length);
    for (let i=0; i<binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
    const data = await new Response(stream).json();
    if (!data.buildings || !data.roads || !data.water) throw new Error('Invalid Shanghai scenery database');
    if (data.packing === 'delta-decimetres') {
      const unpack = values => { const points=[]; let x=0,z=0; for(let i=0;i<values.length;i+=2){x+=values[i];z+=values[i+1];points.push([x/10,z/10]);}return points; };
      for(const feature of [...data.buildings,...data.water,...(data.parks||[])]){feature.polygon=unpack(feature.polygon);if(feature.holes)feature.holes=feature.holes.map(unpack);}
      for(const feature of data.roads)feature.points=unpack(feature.points);
      delete data.packing;
    }
    return data;
  })().catch(error => { loaded = undefined; throw error; });
  return loaded;
}
